/* 第二關後續程序：同一套實體文件元件與獨立場景。 */
let g2={stage:null,selected:null,agenda:[],branch:{},sign:18,pieces:[],order:[],folder:[]};
const gc=s=>document.querySelector(s),G2B=id=>LEVEL2_CONTENT.bills[id];
function g2Token(id){let b=G2B(id),o=GATE2_BILL_OBJECTS[id],marks=o.marks.map(x=>`<i>${x}</i>`).join('');return`<button class="flow-bill ${id}" data-doc="${id}" onclick="g2Pick('${id}')"><small>${b.tag}</small><b>${b.name}</b><em>${marks}</em></button>`}
function g2Pick(x){g2.selected=x;document.querySelectorAll('[data-doc]').forEach(e=>e.classList.toggle('picked',e.dataset.doc===x))}
function g2Drop(zone){if(!g2.selected)return;let x=g2.selected;g2.selected=null;g2Act(x,zone)}
function g2Stamp(id,text){let o=GATE2_BILL_OBJECTS[id];if(!o.marks.includes(text))o.marks.push(text)}function g2Folder(name,content=''){if(!g2.folder.some(x=>(x.name||x)===name))g2.folder.push({name,content})}
function g2FolderView(i){let d=g2.folder[i];modal(`<button class="close" onclick="openGate2Folder()">×</button><div class="gate2-folder-panel"><h2>${d.name}</h2><p>${d.content||'程序文件已整理收存。'}</p></div>`)}
openGate2Folder=function(){modal(`<button class="close" onclick="document.querySelector('#modal')?.remove()">×</button><div class="gate2-folder-panel"><h2>文件夾</h2>${g2.folder.length?g2.folder.map((x,i)=>`<button class="folder-row" onclick="g2FolderView(${i})">▰ ${x.name||x}</button>`).join(''):'<p>目前沒有收入程序文件。</p>'}</div>`)};
function g2Hud(){return`<header class="gate2-hud"><div class="mission"><b>貳｜尚未完成的法案</b><br><span>立法程序紀錄</span></div><button class="folder-hud" onclick="openGate2Folder()" aria-label="開啟文件夾">▰<small>文件夾</small></button></header>`}
function g2Scene(kind,body){app.innerHTML=`<section class="flow-scene ${kind}">${g2Hud()}<main class="flow-table"><div class="flow-title">${kind==='committee'?'委員會會議室':kind==='negotiation'?'黨團協商':'立法院議場'}</div>${body}</main><div class="flow-message" id="flow-message"></div></section>`;bindFlowDrag()}function g2Msg(t){let e=gc('#flow-message');if(e)e.textContent=t}function g2Next(stage,msg){g2.stage=stage;g2Msg(msg||'');setTimeout(g2Render,msg?850:0)}function g2Render(){({agenda,first,branch,committee,committeeexit,direct,directexit,negotiation,second,third,promulgation,effective,complete}[g2.stage]||agenda)()}
function g2AgendaDocument(id){let b=G2B(id),isBlue=id==='blue';return`<button class="agenda-document ${id}" data-doc="${id}" onclick="g2Pick('${id}')" aria-label="拿起${isBlue?'行政院案':'委員案'}"><span class="agenda-doc-tag">${isBlue?'法律案':'委員提案'}</span><b>${b.name}</b><small>${b.by}</small>${isBlue?'':'<i>連署頁</i>'}</button>`}
function agenda(){let queued=id=>g2.agenda.includes(id);g2Scene('chamber agenda-scene',`<p class="agenda-instruction">法律案已經提出。下一站是哪裡？</p><div class="agenda-desk"><div class="agenda-book"><em>議事日程</em><b>程序委員會紀錄</b><small>待排入院會議程的法律案</small></div><div class="agenda-tray-art" aria-hidden="true"></div><button class="agenda-tray procedure ${queued('blue')&&queued('orange')?'full':''}" data-zone="procedure" onclick="g2Drop('procedure')"><b>程序委員會</b><small>議事日程</small><span>${g2.agenda.map(x=>`<i class="mini-file ${x}">${G2B(x).tag}</i>`).join('')||'文件盤'}</span></button><button class="agenda-tray committee" data-zone="committee" onclick="g2Drop('committee')"><b>委員會審查</b><small>審查法案</small></button><button class="agenda-tray second" data-zone="second" onclick="g2Drop('second')"><b>第二讀會</b><small>院會程序</small></button></div><div class="agenda-docs">${queued('blue')?'':g2AgendaDocument('blue')}${queued('orange')?'':g2AgendaDocument('orange')}</div><div class="flow-message" id="flow-message"></div>`)}
function first(){g2Scene('chamber',`<article class="reading-record"><h2>第一讀會</h2><p>主席台前的程序紀錄</p></article><div class="paper-slips">${['朗讀議案標題','逐條討論','全案表決'].map(x=>`<button onclick="g2First('${x}')">${x}</button>`).join('')}</div>`)}function g2First(x){if(x!=='朗讀議案標題')return g2Msg('程序還沒有走到這裡。');g2Stamp('blue','一讀完成');g2Stamp('orange','一讀完成');g2Next('branch','第一讀會完成。')}
function branch(){g2Scene('chamber',`<div class="branch-record"><p>行政院案：交付委員會審查</p><p>委員案：有人提議逕付二讀</p></div><div class="flow-bills">${g2Token('blue')}${g2Token('orange')}</div><div class="drop-pair"><button data-zone="committee" onclick="g2Drop('committee')">交付委員會審查</button><button data-zone="direct" onclick="g2Drop('direct')">逕付二讀程序</button></div>`)}
function committee(){g2Scene('committee',`<p class="scene-caption">整理委員會審查文件</p><div class="review-folder" data-zone="review" onclick="g2Drop('review')">委員會審查資料夾<br><small>${g2.review||0} / 3</small></div><div class="paper-slips"><button data-doc="review:修正意見" onclick="g2Pick('review:修正意見')">修正意見</button><button data-doc="review:保留意見" onclick="g2Pick('review:保留意見')">保留意見</button><button data-doc="review:審查資料" onclick="g2Pick('review:審查資料')">審查資料</button></div>`)}
function committeeexit(){g2Scene('committee',`<article class="review-report"><h2>委員會審查報告</h2><p>本案部分條文仍有爭議，決議交付黨團協商。</p></article>${g2Token('blue')}<div class="drop-pair"><button data-zone="second" onclick="g2Drop('second')">第二讀會</button><button data-zone="negotiation" onclick="g2Drop('negotiation')">黨團協商</button></div>`)}
function direct(){g2Scene('chamber',`<article class="signature-book"><h2>逕付二讀程序紀錄</h2><p>有人提議 ✓</p><p>連署／附議：<b>${g2.sign} / 20</b></p></article><div class="name-strips">${['林委員','許委員','周委員','方委員','吳委員'].map((x,i)=>`<button data-doc="sign${i}" onclick="g2Pick('sign${i}')">${x}</button>`).join('')}</div><button class="signature-tray" data-zone="sign" onclick="g2Drop('sign')">連署名冊</button><button class="vote-device" ${g2.sign>=20?'':'disabled'} onclick="g2Vote()">院會表決</button>`)}function g2Vote(){g2Stamp('orange','逕付二讀');g2Next('directexit','院會表決：通過。')}
function directexit(){g2Scene('chamber',`${g2Token('orange')}<article class="direct-note">逕付二讀之議案，應交付黨團協商。</article><div class="drop-pair"><button data-zone="second" onclick="g2Drop('second')">第二讀會</button><button data-zone="negotiation" onclick="g2Drop('negotiation')">黨團協商</button></div>`)}
const NEG_DOCS={nhead:{title:'黨團協商結論',text:'協商文件抬頭與案名'},nbody:{title:'協商內容',text:'本案部分條文依協商內容修正……'},nsign:{title:'協商結論',text:'代表簽署欄｜確認結論'},nreport:{title:'委員會審查報告',text:'審查完竣・前一階段文件'},nsecond:{title:'第二讀會逐條討論紀錄',text:'尚未進入第二讀會'}};
function g2DocPaper(id){let d=NEG_DOCS[id];return`<button class="neg-paper ${id}" data-doc="${id}" onclick="g2Pick('${id}')"><b>${d.title}</b><small>${d.text}</small></button>`}
function negotiation(){let inSlot=i=>g2.negSlots?.[i];g2Scene('negotiation',`<p class="scene-caption">從桌面的文件中，修復一份完整的協商結論。</p><div class="neg-board"><div class="neg-board-art"></div><div class="neg-title">黨團協商結論</div>${[0,1,2].map(i=>`<button class="neg-slot" data-zone="n${i}" onclick="g2Drop('n${i}')"><i>①②③</i><span>${inSlot(i)?g2DocPaper(inSlot(i)):''}</span></button>`).join('')}</div><div class="neg-scatter">${Object.keys(NEG_DOCS).filter(id=>!g2.negSlots?.includes(id)).map(g2DocPaper).join('')}</div>${g2.negotiationReady?'<button class="neg-stamp" data-zone="neg-stamp" onclick="g2Drop(\'neg-stamp\')">黨團協商<br>完成</button>':''}`)}
const ORDER_CARDS=['廣泛討論','逐條討論','條文議決'];
function g2OrderPaper(name){return`<button class="order-paper" data-doc="order:${name}" onclick="g2Pick('order:${name}')"><b>${name}</b><small>第二讀會程序</small></button>`}
function second(){let used=g2.order||[];let source=(g2.orderPool||['條文議決','廣泛討論','逐條討論']).filter(x=>!used.includes(x)),full=used.filter(Boolean).length===3;g2Scene('chamber',`<p class="scene-caption">把議事程序紙條依序放回紀錄板。</p><div class="order-desk"><div class="order-record">第二讀會程序紀錄</div><div class="order-slots">${[0,1,2].map(i=>`<button class="order-slot" data-zone="o${i}" onclick="g2Drop('o${i}')"><i>${['①','②','③'][i]}</i>${used[i]?g2OrderPaper(used[i]):''}</button>`).join('')}</div><button class="order-confirm ${full?'ready':''}" onclick="g2ConfirmOrder()">確認程序</button></div><div class="order-scatter">${source.map(g2OrderPaper).join('')}</div>`)}
function g2ConfirmOrder(){if((g2.order||[]).filter(Boolean).length<3)return;let ok=g2.order.join('|')==='廣泛討論|逐條討論|條文議決';if(!ok){document.querySelector('.order-desk')?.classList.add('order-shake');g2Msg('程序順序似乎不對，再檢查一次。');setTimeout(()=>document.querySelector('.order-desk')?.classList.remove('order-shake'),450);return}g2Stamp('blue','二讀完成');g2Stamp('orange','二讀完成');g2Next('third','第二讀會程序紀錄已確認。')}
function third(){g2Scene('chamber dark',`<article class="third-paper"><h2>第三讀會</h2><p>原文：「違反者處新臺幣一萬元罰鍰。」</p><p>修正：「違反者處新臺幣十萬元罰鍰。」</p><button onclick="g2Third('reject')">退回</button><button onclick="g2Third('accept-big')">接受修正</button></article>${g2.third===1?'<article class="third-paper"><p>「應予以通知」 → 「應通知」</p><button onclick="g2Third(\'accept-small\')">接受文字修正</button><button onclick="g2Third(\'reject-small\')">退回</button></article>':''}${g2.third===2?'<button class="vote-device" onclick="g2ThirdVote()">全案表決</button>':''}`)}function g2Third(x){if(x==='accept-big')return g2Msg('這不只是文字修正。');if(x==='reject'){g2.third=1;return g2Render()}if(x==='accept-small'){g2.third=2;return g2Render()}g2Msg('這是文字修正，可接受。')}function g2ThirdVote(){g2Stamp('blue','三讀通過');g2Stamp('orange','三讀通過');g2Next('promulgation','三讀通過。')}
function promulgation(){g2Scene('chamber',`<article class="formal-envelope"><h2>三讀通過</h2><p>三讀通過 ✓<br>公布 □<br>生效 □</p><button onclick="g2Msg('三讀通過，還不是法律生效。')">完成</button><p>立法院咨請總統公布</p><button class="btn light" onclick="g2Next('effective','確認公布紀錄：10月12日。')">確認公布紀錄</button></article>`)}
function effective(){g2Scene('chamber',`<p class="scene-caption">把「生效」印章蓋在正確日期。</p><button class="ink" data-doc="effective" onclick="g2Pick('effective')">生效</button><div class="calendar">${['10/12|公布｜第一日','10/13|第二日','10/14|第三日','10/15|'].map((x,i)=>{let a=x.split('|');return`<button data-zone="date${i}" onclick="g2Drop('date${i}')"><b>${a[0]}</b><small>${a[1]}</small></button>`}).join('')}</div>`)}
function complete(){g2Scene('chamber',`<article class="completion-paper"><div class="stampbig">程序完成</div><h2>提案 → 程序委員會 → 一讀 → 分流</h2><p>行政院案：委員會審查 → 本案交付協商<br>委員案：逕付二讀 → 黨團協商【必經】<br>→ 二讀 → 三讀 → 總統公布 → 生效</p><button class="btn light" onclick="notebook02()">公民筆記02｜立法程序</button><button class="btn" onclick="gate2TestEntry()">重新測試第二關</button></article>`)}
function g2AgendaReject(zone){let tray=gc(`.agenda-tray.${zone}`);tray?.classList.add('wrong-drop');setTimeout(()=>tray?.classList.remove('wrong-drop'),420);g2Msg(zone==='committee'?'尚未經院會交付，不能直接進入委員會審查。':'程序尚未走到第二讀會。')}
function g2AgendaComplete(){g2Stamp('blue','議事日程審定');g2Stamp('orange','議事日程審定');g2Render();let desk=gc('.agenda-desk');if(desk){let stamp=document.createElement('div');stamp.className='agenda-stamp';stamp.innerHTML='<b>議事日程審定</b><small>兩案已排入院會議程。</small>';desk.append(stamp)}setTimeout(()=>{g2.stage='first';g2Render()},1150)}
function g2Act(x,z){if(g2.stage==='agenda'&&(x==='blue'||x==='orange')){if(z!=='procedure')return g2AgendaReject(z);if(!g2.agenda.includes(x))g2.agenda.push(x);if(g2.agenda.length===2)return g2AgendaComplete();return g2Render()}if(g2.stage==='branch'){let ok=(x==='blue'&&z==='committee')||(x==='orange'&&z==='direct');if(!ok)return g2Msg('這份議案的程序紀錄不是這樣。');g2.branch[x]=z;if(g2.branch.blue&&g2.branch.orange){g2.stage='committee';return g2Render()}return g2Render()}if(g2.stage==='committee'&&x.startsWith('review:')&&z==='review'){g2.review=(g2.review||0)+1;if(g2.review===3){g2Folder('委員會審查報告');g2Stamp('blue','審查完竣');return g2Next('committeeexit','取得：委員會審查報告')}return g2Render()}if(g2.stage==='committeeexit'){if(z!=='negotiation')return g2Msg('看看這份審查紀錄。');return g2Next('direct','行政院案已交付黨團協商。')}if(g2.stage==='direct'&&x.startsWith('sign')&&z==='sign'){g2.sign=Math.min(20,g2.sign+1);return g2Render()}if(g2.stage==='directexit'){if(z!=='negotiation')return g2Msg('程序還少了一步。');return g2Next('negotiation','兩案在黨團協商會合。')}if(g2.stage==='negotiation'){if(z==='neg-stamp'&&g2.negotiationReady){g2Folder('黨團協商結論','本案部分條文依協商內容修正；代表簽署確認結論。');return g2Next('second','黨團協商完成。')}if(!z.startsWith('n'))return;let slot=+z.slice(1);if(x==='nreport')return g2Msg('這是前一階段留下的審查文件。');if(x==='nsecond')return g2Msg('這份紀錄現在還不會出現。');let expected=['nhead','nbody','nsign'][slot];if(x!==expected)return g2Msg('文件的位置似乎不對。');g2.negSlots=g2.negSlots||[];g2.negSlots[slot]=x;if(g2.negSlots.filter(Boolean).length===3)g2.negotiationReady=true;return g2Render()}if(g2.stage==='second'&&x.startsWith('order:')&&z.startsWith('o')){let p=x.slice(6),slot=+z.slice(1);g2.order=g2.order||[];let old=g2.order[slot];g2.order=g2.order.filter(Boolean);let prior=g2.order.indexOf(p);if(prior>-1)g2.order[prior]=old;else g2.order[slot]=p;g2.order.length=Math.max(g2.order.length,slot+1);return g2Render()}if(g2.stage==='effective'&&x==='effective'){if(z!=='date2')return g2Msg('再看一次公布日的起算方式。');g2Folder('公布紀錄');return g2Next('complete','法律生效 ✓　10/12第一日、10/13第二日、10/14第三日。')}}
function bindFlowDrag(){document.querySelectorAll('[data-doc]').forEach(e=>e.addEventListener('pointerdown',v=>{g2Pick(e.dataset.doc);window.g2DraggingId=e.dataset.doc;e.setPointerCapture?.(v.pointerId);v.preventDefault()}));if(!window.__g2FlowPointerBound){window.__g2FlowPointerBound=true;document.addEventListener('pointerup',v=>{if(!window.g2DraggingId)return;let zone=document.elementFromPoint(v.clientX,v.clientY)?.closest('[data-zone]');let held=window.g2DraggingId;window.g2DraggingId=null;if(zone&&g2.selected===held)g2Drop(zone.dataset.zone)})}document.querySelectorAll('[data-zone]').forEach(e=>e.addEventListener('pointerup',v=>{if(g2.selected){window.g2DraggingId=null;g2Drop(e.dataset.zone);v.preventDefault()}}))}
const oldReturn=returnProposal;returnProposal=function(id){oldReturn(id);if(GATE2_BILL_OBJECTS.blue.viewed&&GATE2_BILL_OBJECTS.orange.viewed){setTimeout(()=>{g2.stage='agenda';g2Render()},450)}};
gate2TestEntry=function(){g2={stage:null,selected:null,agenda:[],branch:{},sign:18,pieces:[],order:[],folder:[]};Object.values(GATE2_BILL_OBJECTS).forEach(x=>{x.viewed=false;x.marks=[];x.status='draft'});l2={...L2,gate2Started:true};lsave();render2()};
